export function validateThresholds(thresholds = {}, metricIds) {
  const errors = [];
  const validMetrics = new Set(metricIds);

  for (const [metric, min] of Object.entries(thresholds)) {
    if (!validMetrics.has(metric)) {
      errors.push(`Unknown metric: ${metric}. Valid metrics: ${Array.from(validMetrics).join(', ')}`);
    } else if (typeof min !== 'number' || min < 0 || min > 1) {
      errors.push(`Invalid threshold for ${metric}: must be a number between 0 and 1, got ${min}`);
    }
  }

  return errors;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds = {},
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const metricIds = evaluations.map((m) => m.id);
  const thresholdErrors = validateThresholds(thresholds, metricIds);
  if (thresholdErrors.length > 0) {
    throw new Error(`Threshold validation failed: ${thresholdErrors.join('; ')}`);
  }

  const thresholdResults = [];
  let allPassed = true;

  for (const [metric, min] of Object.entries(thresholds)) {
    const evaluation = evaluations.find((m) => m.id === metric);
    const score = evaluation?.score;
    const passed = score !== null ? score >= min : false;

    thresholdResults.push({
      metric,
      min,
      score,
      passed
    });

    if (!passed) {
      allPassed = false;
    }
  }

  return {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations,
    ...(Object.keys(thresholds).length > 0 && {
      passed: allPassed,
      thresholds: thresholdResults
    })
  };
}

